/// The encoding of a key some typed entry carries ahead of its `type`.
#[must_use]
pub fn pre_type_encoding(key: &[u8]) -> Option<Enc> {
    match key {
        b"css" => Some(Enc::Record),
        b"end" => Some(Enc::Offset),
        b"js" => Some(Enc::List),
        b"start" => Some(Enc::Offset),
        _ => None,
    }
}
